//SOUND_BEGIN
// =========================================================================
// Title: Trailing the Twinkling Tunnelwisp (Audio)
// Author: mrange
// Source: https://www.shadertoy.com/view/WfcGWj
//
// Original Music: Pestis, created for Cassini's Cosmic Conclusion
//                 https://demozoo.org/productions/367582/
// Also available as a twigl: https://twigl.app?ol=true&ss=-OQdLCgeO21o1boSdWJO
// 
// License: CC0 1.0 Universal (Public Domain Dedication)
//          https://creativecommons.org/publicdomain/zero/1.0/
//
// Note: Adapted for the "Surfaces Explorer" engine.
// =========================================================================

vec2 mainSound(int s, float t) {
  vec2 r = vec2(0.0); // FIX 1: Inizializzato a zero

  // FIX 2: i e j inizializzati a zero
  for(float i = 0.0, j = 0.0; ++i < 4.0;)
  for(j = 0.0; ++j < 5.0;) {

    float a = t * j / 32.0 + i / 3.0;
    float b = fract(a);
    float c;

    // FIX 3: m inizializzato a zero
    vec2 m = vec2(0.0); 
    vec2 n = vec2(t, t + 3.0) + t / j;

    for(c = 3.0; c < 4.1; n += c *= 1.02)
      m += sin(n * c) / c;

    if(a < 9.0)
      r += sin(m + 4.0 * sin(t / j / 47.0) * sin(exp2(mod(a - b, 3.0) / 6.0 + 8.5) * t * j * i + i + j))
      * exp2(-b * 12.0 - 1.0 / b + 6.0 - (i + j) / 3.0);
  }
  return r;
}
//SOUND_END

// Distance from the center (Y axis) for the rings
float dist = pModel.y;

// 'fract' creates crisp stripes (rings); -u_time expands them outward
float anelli = fract(dist * 10.0 - ubuf.u_time * 2.0);

// Slightly softened edges
anelli = smoothstep(0.0, 0.2, anelli) * smoothstep(1.0, 0.8, anelli);

// Background = u_col2, rings = u_col1 (dock colors)
textureCol = mix(ubuf.u_col2, ubuf.u_col1, anelli);
